import React from 'react';
import { TreeSelect, Select, FormItem, FormButtonGroup, Submit } from '@storage-fe/formily-arco';
import { createForm, onFieldReact, FormPathPattern, Field as FieldType } from '@formily/core';
import { FormProvider, Field } from '@formily/react';
import { action } from '@formily/reactive';
import { TreeSelectDataType } from '@arco-design/web-react/es/TreeSelect/interface';

const AsyncDataSourceEffect = (
  pattern: FormPathPattern,
  service: (field: FieldType) => Promise<TreeSelectDataType[]>
) => {
  onFieldReact(pattern, (field: FieldType) => {
    field.loading = true;
    service(field).then(
      action.bound?.(data => {
        field.dataSource = data;
        field.loading = false;
      })
    );
  });
};

const form = createForm({
  effects: () => {
    AsyncDataSourceEffect('select', async field => {
      const linkage = field.query('linkage').get('value');
      if (!linkage) {
        return [];
      }
      return new Promise(resolve => {
        setTimeout(() => {
          if (linkage === 1) {
            resolve([
              {
                title: 'AAA',
                value: 'aaa',
                children: [
                  {
                    title: 'Child Node1',
                    value: '0-0-0',
                    key: '0-0-0',
                  },
                  {
                    title: 'Child Node2',
                    value: '0-0-1',
                    key: '0-0-1',
                  },
                  {
                    title: 'Child Node3',
                    value: '0-0-2',
                    key: '0-0-2',
                  },
                ],
              },
              {
                title: 'BBB',
                value: 'ccc',
                children: [
                  {
                    title: 'Child Node1',
                    value: '0-1-0',
                    key: '0-1-0',
                  },
                  {
                    title: 'Child Node2',
                    value: '0-1-1',
                    key: '0-1-1',
                  },
                  {
                    title: 'Child Node3',
                    value: '0-1-2',
                    key: '0-1-2',
                  },
                ],
              },
            ]);
          } else if (linkage === 2) {
            resolve([
              {
                title: 'CCC',
                value: 'ccc',
                children: [
                  {
                    title: 'Child Node1',
                    value: '0-0-0',
                    key: '0-0-0',
                  },
                  {
                    title: 'Child Node2',
                    value: '0-0-1',
                    key: '0-0-1',
                  },
                  {
                    title: 'Child Node3',
                    value: '0-0-2',
                    key: '0-0-2',
                  },
                ],
              },
              {
                title: 'DDD',
                value: 'ddd',
                children: [
                  {
                    title: 'Child Node1',
                    value: '0-1-0',
                    key: '0-1-0',
                  },
                  {
                    title: 'Child Node2',
                    value: '0-1-1',
                    key: '0-1-1',
                  },
                  {
                    title: 'Child Node3',
                    value: '0-1-2',
                    key: '0-1-2',
                  },
                ],
              },
            ]);
          }
        }, 1500);
      });
    });
  },
});

export default () => (
  <FormProvider form={form}>
    <Field
      name="linkage"
      title="联动选择框"
      dataSource={[
        { label: '发请求1', value: 1 },
        { label: '发请求2', value: 2 },
      ]}
      decorator={[FormItem]}
      component={[
        Select,
        {
          style: {
            width: 200,
          },
        },
      ]}
    />
    <Field
      name="select"
      title="异步选择框"
      decorator={[FormItem]}
      component={[
        TreeSelect,
        {
          style: {
            width: 200,
          },
        },
      ]}
    />
    <FormButtonGroup>
      <Submit onSubmit={console.log}>提交</Submit>
    </FormButtonGroup>
  </FormProvider>
);
